import 'package:audioplayers/audioplayers.dart';

/// The court's little brass section. Sounds live in assets/sounds and were
/// generated by tool/synth_sounds.py.
class Sfx {
  Sfx._();

  /// Players' choice, saved with their settings.
  static bool enabled = true;

  /// Tests have no audio plugin; they switch sound off entirely.
  static bool muteForTests = false;

  static final Map<String, AudioPlayer> _players = {};

  static Future<void> _play(String name) async {
    if (!enabled || muteForTests) return;
    try {
      final player = _players.putIfAbsent(name, () {
        final p = AudioPlayer();
        p.setReleaseMode(ReleaseMode.stop);
        return p;
      });
      await player.stop();
      await player.play(AssetSource('sounds/$name.wav'), volume: 0.8);
    } catch (_) {
      // No audio on this device: stay silent.
    }
  }

  static void fanfare() => _play('fanfare');
  static void win() => _play('win');
  static void lose() => _play('lose');
}
